sys_ui_page.client_script:
window.addEventListener(
    'load',
    function() {

        loadAttendanceHistory();

    }
);


// =============================================================
// LOAD ATTENDANCE HISTORY
// =============================================================
function loadAttendanceHistory() {

    var loadingBox =
        document.getElementById(
            'loadingBox'
        );

    var historyContainer =
        document.getElementById(
            'historyContainer'
        );

    var summaryCard =
        document.getElementById(
            'summaryCard'
        );


    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/my-attendance',
        {
            method: 'GET',

            credentials:
                'same-origin',

            headers: {

                'X-UserToken':
                    window.g_ck || ''
            }
        }
    )

    .then(function(response) {

        return response
            .json()
            .then(function(data) {

                return {

                    ok:
                        response.ok,

                    data:
                        data
                };

            });

    })

    .then(function(result) {

        if (
            !result.ok ||
            !result.data.result ||
            !result.data.result.success
        ) {

            throw new Error(
                'Unable to load attendance history.'
            );
        }


        var data =
            result.data.result;


        // -----------------------------------------------------
        // Employee summary
        // -----------------------------------------------------
        document.getElementById(
            'employeeName'
        ).innerHTML =
            data.employee || 'Employee';


        document.getElementById(
            'recordCount'
        ).innerHTML =
            'Showing ' +
            parseInt(
                data.count || 0,
                10
            ) +
            ' attendance record(s)';


        summaryCard.style.display =
            'block';


        loadingBox.style.display =
            'none';


        // -----------------------------------------------------
        // No attendance
        // -----------------------------------------------------
        if (
            !data.attendance ||
            data.attendance.length === 0
        ) {

            historyContainer.innerHTML =
                '<div class="empty">' +
                    'No attendance records found.' +
                '</div>';

            historyContainer.style.display =
                'block';

            return;
        }


        // -----------------------------------------------------
        // Render records
        // -----------------------------------------------------
        var html = '';


        for (
            var i = 0;
            i < data.attendance.length;
            i++
        ) {

            var record =
                data.attendance[i];


            html +=
                buildAttendanceCard(
                    record
                );
        }


        historyContainer.innerHTML =
            html;


        historyContainer.style.display =
            'block';

    })

    .catch(function(error) {

        console.error(
            'Attendance History Error:',
            error
        );


        loadingBox.className =
            'error';


        loadingBox.innerHTML =
            error.message ||
            'Unable to load attendance history.';

    });
}



// =============================================================
// BUILD ATTENDANCE CARD
// =============================================================
function buildAttendanceCard(
    record
) {

    var statusText =
        formatStatus(
            record.status
        );


    var statusClass =
        getStatusClass(
            record.status
        );


    var checkIn =
        formatDateTime(
            record.check_in
        );


    var checkOut =
        formatDateTime(
            record.check_out
        );


    var workingMinutes =
        record.working_minutes
            ? record.working_minutes
            : '-';


    var lateMinutes =
        record.late_minutes
            ? record.late_minutes
            : '0';


    return (

        '<div class="attendance-card">' +

            '<div class="attendance-top">' +

                '<div>' +

                    '<div class="attendance-date">' +
                        escapeHtml(
                            formatDate(
                                record.attendance_date
                            )
                        ) +
                    '</div>' +

                    '<div class="detail-label">' +
                        escapeHtml(
                            record.number || ''
                        ) +
                    '</div>' +

                '</div>' +

                '<div class="status-badge ' +
                    statusClass +
                '">' +

                    escapeHtml(
                        statusText
                    ) +

                '</div>' +

            '</div>' +


            '<div class="details-grid">' +


                buildDetailBox(
                    'Check In',
                    checkIn || '-'
                ) +


                buildDetailBox(
                    'Check Out',
                    checkOut || '-'
                ) +


                buildDetailBox(
                    'Late Minutes',
                    lateMinutes
                ) +


                buildDetailBox(
                    'Working Minutes',
                    workingMinutes
                ) +


                buildDetailBox(
                    'Scanner',
                    record.scanner || '-'
                ) +


            '</div>' +

        '</div>'

    );
}



// =============================================================
// DETAIL BOX
// =============================================================
function buildDetailBox(
    label,
    value
) {

    return (

        '<div class="detail-box">' +

            '<div class="detail-label">' +
                escapeHtml(label) +
            '</div>' +

            '<div class="detail-value">' +
                escapeHtml(
                    String(value)
                ) +
            '</div>' +

        '</div>'

    );
}



// =============================================================
// FORMAT STATUS
// =============================================================
function formatStatus(
    status
) {

    if (status === 'present') {
        return 'Present';
    }

    if (status === 'late') {
        return 'Late';
    }

    if (status === 'half_day') {
        return 'Half Day';
    }

    if (
        status ===
        'insufficient_hours'
    ) {

        return 'Insufficient Hours';
    }

    return status || '-';
}



// =============================================================
// STATUS STYLE
// =============================================================
function getStatusClass(
    status
) {

    if (status === 'present') {
        return 'status-present';
    }

    if (status === 'late') {
        return 'status-late';
    }

    if (status === 'half_day') {
        return 'status-half';
    }

    return 'status-insufficient';
}



// =============================================================
// FORMAT DATE
// =============================================================
function formatDate(
    dateValue
) {

    if (!dateValue) {
        return '-';
    }


    var parts =
        dateValue.split('-');


    if (parts.length !== 3) {
        return dateValue;
    }


    return (
        parts[2] +
        '-' +
        parts[1] +
        '-' +
        parts[0]
    );
}



// =============================================================
// FORMAT DATETIME
// =============================================================
function formatDateTime(
    dateTime
) {

    if (!dateTime) {
        return '';
    }


    var parts =
        dateTime.split(' ');


    if (
        parts.length < 2
    ) {

        return dateTime;
    }


    return parts[1];
}



// =============================================================
// BASIC HTML ESCAPE
// =============================================================
function escapeHtml(
    value
) {

    return String(value)

        .replace(
            /&/g,
            '&amp;'
        )

        .replace(
            /</g,
            '&lt;'
        )

        .replace(
            />/g,
            '&gt;'
        )

        .replace(
            /"/g,
            '&quot;'
        )

        .replace(
            /'/g,
            '&#039;'
        );
}
